// metrics.query: Read windows of metric series of a connection
// Generated by `pnpm nx g @app/generators:action metrics.query`, then edited. Run
// `pnpm nx run contracts:api-docs` so the committed API documents follow.
//
// Windowed (I-7): at most 50 series and 2,000 points each, over a time range, thinned to the
// caller's `maxPoints`. A series the engine does not hold is `found: false` with no points, never a
// zero; the status says whether the source is live, stale or partial and what was dropped (I-13).
import { z } from 'zod';

import { ConnectionIdSchema } from '../brands.ts';
import { defineAction } from '../kit/define-action.ts';
import {
  MetricsStatusSchema,
  POINTS_MAX,
  SERIES_QUERY_MAX,
  SeriesRefSchema,
} from './metrics-types.ts';

const count = z.number().int().nonnegative();

export const MetricsQueryInputSchema = z.strictObject({
  cid: ConnectionIdSchema,
  series: z.array(SeriesRefSchema).min(1).max(SERIES_QUERY_MAX),
  /** Epoch ms bounds, both inclusive. Default: everything the hot window holds. */
  from: count.optional(),
  to: count.optional(),
  /** Thins the answer to at most this many points per series (the last point of each bucket). */
  maxPoints: z.number().int().min(1).max(POINTS_MAX).default(600),
  /** Counters come back as per-second rates (a reset interval is skipped); gauges are unchanged. */
  rate: z.boolean().optional(),
});

export const MetricsSeriesResultSchema = z.strictObject({
  ref: SeriesRefSchema,
  /** False when the engine holds no such series: no points, not zeros. */
  found: z.boolean(),
  kind: z.enum(['gauge', 'counter']).optional(),
  unit: z.enum(['messages', 'count', 'bytes']).optional(),
  source: z.enum(['prometheus', 'management']).optional(),
  /** Derived from management sampling: a coarse figure. */
  approximate: z.boolean().optional(),
  /** `rate`: per-second rates of a counter. */
  view: z.enum(['value', 'rate']),
  /** `[epoch ms, value]`, oldest first. */
  points: z.array(z.tuple([count, z.number()])).max(POINTS_MAX),
  /** Points this series' ring has evicted since it began. */
  dropped: count,
});

export const MetricsQueryOutputSchema = z.strictObject({
  series: z.array(MetricsSeriesResultSchema).max(SERIES_QUERY_MAX),
  status: MetricsStatusSchema,
});

export const metricsQuery = defineAction({
  id: 'metrics.query',
  kind: 'query',
  summary: 'Read windows of metric series of a connection',
  input: MetricsQueryInputSchema,
  output: MetricsQueryOutputSchema,
  permission: 'broker.read',
  risk: 'none',
  planning: 'none',
  audit: 'none',
  target: (input) => ({ connectionId: input.cid }),
  http: { method: 'POST', path: '/connections/{cid}/metrics/queries' },
  since: '1.0',
});
